function hexToRgb(hex){hex=hex.replace('#','');return [parseInt(hex.slice(0,2),16),parseInt(hex.slice(2,4),16),parseInt(hex.slice(4,6),16)];}
function srgb(v){v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);}
function lum(hex){const [r,g,b]=hexToRgb(hex);return 0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b);}
function contrast(a,b){const L1=lum(a),L2=lum(b);const [hi,lo]=L1>L2?[L1,L2]:[L2,L1];return ((hi+0.05)/(lo+0.05)).toFixed(2);}
const pairs=[['#5d6880','#ffffff'],['#b2bdd3','#111a2b'],['#5b7cff','#ffffff'],['#8aa0ff','#111a2b']];
for(const [fg,bg] of pairs) console.log(`${fg} on ${bg}: ${contrast(fg,bg)}:1`);
