         --surface: rgba(16, 24, 40, 0.82);
         --surface-strong: #111a2b;
         --text: #eef2ff;
         --muted: #b2bdd3;
         --border: rgba(214, 223, 255, 0.16);
         --accent: #8aa0ff;
         --accent-strong: #b8c5ff;
         --shadow: 0 22px 54px rgba(0, 0, 0, 0.35);
       }
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background:
         radial-gradient(circle at top left, rgba(91, 124, 255, 0.18), transparent 28%),
         radial-gradient(circle at right, rgba(98, 220, 192, 0.12), transparent 24%),
         var(--bg);
       color: var(--text);
       line-height: 1.6;
     }

     a {
       color: inherit;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       transform: translateY(-180%);
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--surface-strong);
       color: var(--text);
       box-shadow: var(--shadow);
       text-decoration: none;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .page-shell {
       width: min(calc(100% - 2rem), var(--max-width));
       margin: 0 auto;
       padding: 3rem 0 4rem;
     }

     .hero {
       display: grid;
       gap: 1.5rem;
       padding: clamp(1.5rem, 3vw, 2.5rem);
       border: 1px solid var(--border);
       border-radius: var(--radius-xl);
       background: var(--surface);
       backdrop-filter: blur(20px);
       box-shadow: var(--shadow);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       width: fit-content;
       padding: 0.45rem 0.8rem;
       border-radius: 999px;
       background: rgba(91, 124, 255, 0.12);
       color: var(--accent-strong);
       font-size: 0.9rem;
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     h1,
     h2,
     p {
       margin: 0;
     }

     .hero h1 {
       max-width: 12ch;
       font-size: clamp(2.4rem, 6vw, 4.8rem);
       line-height: 1.02;
       letter-spacing: -0.04em;
     }

     .hero-copy {
       max-width: 60ch;
       font-size: 1.05rem;
       color: var(--muted);
     }

     .hero-stats {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
       padding: 0;
       margin: 0;
       list-style: none;
     }

     .hero-stats li {
       padding: 0.9rem 1rem;
       border: 1px solid var(--border);
       border-radius: var(--radius-md);
       background: var(--surface-strong);
       min-width: 9rem;
     }

     .hero-stats strong {
       display: block;
       font-size: 1rem;
     }

     .hero-stats span {
       color: var(--muted);
       font-size: 0.95rem;
     }

     .faq-section {
       margin-top: 2rem;
       padding: clamp(1.25rem, 2vw, 1.75rem);
       border-radius: var(--radius-xl);
       border: 1px solid var(--border);
       background: var(--surface);
       backdrop-filter: blur(20px);
       box-shadow: var(--shadow);
     }

     .faq-section > p {
       margin-top: 0.5rem;
       max-width: 62ch;
       color: var(--muted);
     }

     .faq-list {
       display: grid;
       gap: 1rem;
       margin-top: 1.5rem;
     }

     .example {
       border: 1px solid var(--border);
       border-radius: var(--radius-lg);
       background: var(--surface-strong);
       overflow: clip;
     }

     .question-heading {
       margin: 0;
     }

     .question-button {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       width: 100%;
       padding: 1.15rem 1.25rem;
       border: 0;
       background: transparent;
       color: inherit;
       text-align: left;
       font: inherit;
       font-size: 1.05rem;
       font-weight: 700;
       cursor: pointer;
     }

     .question-button:hover {
       background: rgba(91, 124, 255, 0.06);
     }

     .question-button:focus-visible {
       outline: 3px solid var(--accent);
       outline-offset: -3px;
     }

     .question-button::after {
       content: "+";
       flex-shrink: 0;
       width: 2rem;
       height: 2rem;
       display: grid;
       place-items: center;
       border-radius: 999px;
       background: rgba(91, 124, 255, 0.12);
       color: var(--accent-strong);
       font-size: 1.25rem;
       font-weight: 600;
       transition: transform 180ms ease, background-color 180ms ease;
     }

     .question-button[aria-expanded="true"]::after {
       content: "\2212";
       transform: rotate(180deg);
     }

     .details {
       padding: 0 1.25rem 1.25rem;
       color: var(--muted);
     }

     .details p + p {
       margin-top: 0.8rem;
     }

     .details strong {
       color: var(--text);
     }

     @media (max-width: 640px) {
       .page-shell {
         width: min(calc(100% - 1rem), var(--max-width));
         padding-top: 1rem;
       }

       .question-button,
       .details {
         padding-left: 1rem;
         padding-right: 1rem;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       html {
         scroll-behavior: auto;
       }

       *,
       *::before,
       *::after {
         transition-duration: 0.01ms !important;
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
       }
     }

     @media (forced-colors: active) {
       .hero,
       .faq-section,
       .example,
       .hero-stats li {
         border-color: CanvasText;
         box-shadow: none;
       }

       .question-button::after,
       .eyebrow {
         border: 1px solid ButtonText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <main id="maincontent" class="page-shell" tabindex="-1">
     <section class="hero" aria-labelledby="page-title">
       <span class="eyebrow">Cat knowledge base</span>
       <h1 id="page-title">Answers for curious cat people.</h1>
       <p class="hero-copy">
         Browse quick, trusted answers about feline behavior, health, and everyday care. Every topic opens on demand so the page stays easy to scan.
       </p>
       <ul class="hero-stats" aria-label="FAQ highlights">
         <li><strong>6 questions</strong><span>Core cat topics</span></li>
         <li><strong>Instant scan</strong><span>Collapsed by default</span></li>
         <li><strong>Keyboard friendly</strong><span>Built with real buttons</span></li>
       </ul>
     </section>

     <section class="faq-section" aria-labelledby="faq-heading">
       <h2 id="faq-heading">Frequently asked questions</h2>
       <p>Open any question to reveal the answer. Each item works independently, so you can compare topics without losing your place.</p>

       <div class="faq-list">
         <div class="example">
           <h3 class="question-heading">
             <button class="question-button" type="button" aria-expanded="true" aria-controls="answer-1" id="question-1">
               Why do cats purr?
             </button>
           </h3>
           <div class="details" id="answer-1" role="region" aria-labelledby="question-1">
             <p>Cats often purr when they feel content, but they can also purr while self-soothing during stress or discomfort.</p>
             <p><strong>Good to know:</strong> context matters, so look at body posture, ears, and appetite along with the purring itself.</p>
           </div>
         </div>

         <div class="example">
           <h3 class="question-heading">
             <button class="question-button" type="button" aria-expanded="true" aria-controls="answer-2" id="question-2">
               How much sleep do cats need?
             </button>
           </h3>
           <div class="details" id="answer-2" role="region" aria-labelledby="question-2">
             <p>Most adult cats sleep between 12 and 16 hours a day, and kittens or older cats may sleep even longer.</p>
             <p>That pattern is normal for a crepuscular animal that naturally conserves energy for bursts of activity.</p>
           </div>
         </div>

         <div class="example">
           <h3 class="question-heading">
             <button class="question-button" type="button" aria-expanded="true" aria-controls="answer-3" id="question-3">
               Why do cats knead blankets and laps?
             </button>
           </h3>
           <div class="details" id="answer-3" role="region" aria-labelledby="question-3">
             <p>Kneading usually comes from kittenhood, when nursing cats press against their mother to stimulate milk flow.</p>
             <p>Adult cats often keep the habit because it feels comforting and helps them settle into a favorite resting spot.</p>
           </div>
         </div>

         <div class="example">
           <h3 class="question-heading">
             <button class="question-button" type="button" aria-expanded="true" aria-controls="answer-4" id="question-4">
               What should cats eat every day?
             </button>
           </h3>
           <div class="details" id="answer-4" role="region" aria-labelledby="question-4">
             <p>Cats are obligate carnivores, so they need nutritionally complete cat food with plenty of animal-based protein and the amino acid taurine.</p>
             <p>Fresh water should always be available, and any major diet change should be introduced gradually.</p>
           </div>
         </div>

         <div class="example">
           <h3 class="question-heading">
             <button class="question-button" type="button" aria-expanded="true" aria-controls="answer-5" id="question-5">
               Why do cats bring toys or “gifts” to people?
             </button>
           </h3>
           <div class="details" id="answer-5" role="region" aria-labelledby="question-5">
             <p>Many cats bring toys to people as part of social play or instinctive hunting behavior.</p>
             <p>It can be a sign that your cat feels secure enough to share, show off, or invite interaction.</p>
           </div>
         </div>

         <div class="example">
           <h3 class="question-heading">
             <button class="question-button" type="button" aria-expanded="true" aria-controls="answer-6" id="question-6">
               How can I make an indoor cat happier?
             </button>
           </h3>
           <div class="details" id="answer-6" role="region" aria-labelledby="question-6">
             <p>Offer climbing spaces, window views, scratching posts, and short daily play sessions that mimic stalking and chasing.</p>
             <p>Rotating toys and creating quiet hiding spots can also help indoor cats feel enriched and secure.</p>
           </div>
         </div>
       </div>
     </section>
   </main>

   <script>
     const disclosureButtons = document.querySelectorAll(".question-button");

     disclosureButtons.forEach((button) => {
       const details = document.getElementById(button.getAttribute("aria-controls"));

       button.setAttribute("aria-expanded", "false");
       details.hidden = true;

       button.addEventListener("click", () => {
         const isExpanded = button.getAttribute("aria-expanded") === "true";
         button.setAttribute("aria-expanded", String(!isExpanded));
         details.hidden = isExpanded;
       });

       button.addEventListener("keydown", (event) => {
         if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
           button.setAttribute("aria-expanded", "false");
           details.hidden = true;
         }
       });
     });
   </script>
 </body>
 </html>

')
